<template><el-card><template #header><div class="header"><div><b>人脸重录审批</b><p>批准后学生获得一次重新录入机会，新人脸录入成功后会再次自动锁定。</p></div><el-button @click="load">刷新</el-button></div></template><el-table v-loading="loading" :data="rows" empty-text="暂无重录申请"><el-table-column prop="student_number" label="学号"/><el-table-column prop="real_name" label="姓名"/><el-table-column prop="reason" label="申请原因" min-width="220"/><el-table-column prop="created_at" label="申请时间" min-width="170"><template #default="{row}">{{format(row.created_at)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='PENDING'?'warning':'success'">{{row.status==='PENDING'?'待审批':'已批准'}}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="row.status==='PENDING'" type="primary" size="small" @click="approve(row)">批准重录</el-button></template></el-table-column></el-table></el-card></template>
<script setup>
import {ref,onMounted} from 'vue';import dayjs from 'dayjs';import {ElMessage,ElMessageBox} from 'element-plus';import {getFaceReEnrollRequests,approveFaceReEnroll} from '@/api/face'
const rows=ref([]),loading=ref(false);const format=v=>v?dayjs(v).format('YYYY-MM-DD HH:mm'):'-';async function load(){loading.value=true;try{rows.value=await getFaceReEnrollRequests()||[]}finally{loading.value=false}}async function approve(row){await ElMessageBox.confirm(`批准 ${row.real_name} 重新录入人脸吗？`,'批准重录',{type:'warning'});await approveFaceReEnroll(row.student_id);ElMessage.success('已批准一次重新录入机会');await load()}onMounted(load)
</script>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center;gap:16px}.header p{margin:6px 0 0;color:#98a2b3;font-size:13px}</style>
